import{_ as t,o,c as a,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const m=JSON.parse('{"title":"Real-time Interaction","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/interaction.md","filePath":"en/features/interaction.md","lastUpdated":1786689844000}'),n={name:"en/features/interaction.md"};function i(s,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="real-time-interaction" tabindex="-1">Real-time Interaction <a class="header-anchor" href="#real-time-interaction" aria-label="Permalink to &quot;Real-time Interaction&quot;">​</a></h1><h2 id="feature-overview" tabindex="-1">Feature Overview <a class="header-anchor" href="#feature-overview" aria-label="Permalink to &quot;Feature Overview&quot;">​</a></h2><p>In a ZViewer room, you and your friends can not only watch videos synchronously but also interact in real time -- send danmaku, chat, use voice, and even draw annotations on the screen with a pen.</p><hr><h2 id="_1-comments-and-chat" tabindex="-1">1. Comments and Chat <a class="header-anchor" href="#_1-comments-and-chat" aria-label="Permalink to &quot;1. Comments and Chat&quot;">​</a></h2><p>The comment panel is located on the <strong>right panel</strong> (CommentPanel) of the room interface, containing three tabs.</p><h3 id="how-to-send-a-comment" tabindex="-1">How to Send a Comment <a class="header-anchor" href="#how-to-send-a-comment" aria-label="Permalink to &quot;How to Send a Comment&quot;">​</a></h3><ol><li>Make sure you are on the <strong>&quot;Comments&quot; tab</strong></li><li>Type your message in the input box at the bottom</li><li>Press Enter or click the send button</li><li>The comment appears immediately, visible to everyone in the room</li></ol><h2 id="_2-viewer-request-for-control" tabindex="-1">2. Viewer Request for Control <a class="header-anchor" href="#_2-viewer-request-for-control" aria-label="Permalink to &quot;2. Viewer Request for Control&quot;">​</a></h2><p>As a viewer, if you want to fast-forward/rewind or pause, you can send a request to the host.</p><ol><li>Click pause or seek on the player</li><li>The system prompts &quot;A request has been sent to the host. Please wait for confirmation.&quot;</li><li>A notification appears at the top-left of the host&#39;s player</li><li>The host clicks approve or deny</li></ol><p>If the host has enabled <strong>&quot;Auto-approve control requests&quot;</strong>, the request takes effect automatically.</p><h2 id="_3-voice-chat" tabindex="-1">3. Voice Chat <a class="header-anchor" href="#_3-voice-chat" aria-label="Permalink to &quot;3. Voice Chat&quot;">​</a></h2><p>The voice chat panel (VoiceChatPanel) is permanently located at the <strong>bottom-right corner</strong> of the page.</p><h3 id="host-enabling-voice" tabindex="-1">Host Enabling Voice <a class="header-anchor" href="#host-enabling-voice" aria-label="Permalink to &quot;Host Enabling Voice&quot;">​</a></h3><ol><li>Click the voice panel at the bottom-right corner</li><li>Enable voice</li><li>Set the bitrate: 32 / 96 / 128 / 192 kbps (default 128 kbps)</li><li>Once enabled, viewers can listen in</li></ol><blockquote><p>Voice uses <strong>server relay mode</strong> (rather than P2P) to address the issue of P2P being blocked in current NAT environments, which would otherwise prevent voice chat. In relay mode, audio streams are forwarded through the server, offering better compatibility without NAT type restrictions.</p><p>The playback pipeline includes an <strong>adaptive jitter buffer</strong> that adjusts buffering based on network jitter, reducing stutter and latency. The codec pipeline locks the sample rate with decoding fallback, making the first word after unmuting sound more natural.</p></blockquote><h3 id="member-identity-and-display" tabindex="-1">Member Identity and Display <a class="header-anchor" href="#member-identity-and-display" aria-label="Permalink to &quot;Member Identity and Display&quot;">​</a></h3><ul><li>Voice members are bound to their <strong>real identity</strong> (logged-in users show their username, guests show their nickname), instead of socketId prefixes.</li><li>When a logged-in user reconnects after a disconnect, they <strong>automatically replace</strong> their old entry, eliminating ghost members from the source (e.g., &quot;3 people in voice showing as 8&quot;).</li><li>The voice panel displays a member list, and you can adjust the speaker volume.</li></ul><h3 id="voice-moderation-host-moderator" tabindex="-1">Voice Moderation (Host / Moderator) <a class="header-anchor" href="#voice-moderation-host-moderator" aria-label="Permalink to &quot;Voice Moderation (Host / Moderator)&quot;">​</a></h3><p>The host or a moderator can manage voice members:</p><ul><li><strong>Voice mute / unmute</strong>: While muted, the server relay layer directly drops the member&#39;s audio packets (enforced server-side; the client cannot bypass it). The muted member can still listen.</li><li><strong>Voice kick</strong>: Kicks a member out of the voice channel (cannot rejoin during a 60-second cooldown).</li></ul><h2 id="_4-moderator-role" tabindex="-1">4. Moderator Role <a class="header-anchor" href="#_4-moderator-role" aria-label="Permalink to &quot;4. Moderator Role&quot;">​</a></h2><p>The host can appoint logged-in users as <strong>moderators</strong> (co-moderators) in the <strong>Viewer Management</strong> panel, up to 10.</p><table tabindex="0"><thead><tr><th>Action</th><th>Host</th><th>Moderator</th><th>Viewer</th></tr></thead><tbody><tr><td>Switch / remove videos</td><td>Yes</td><td>Yes</td><td>No</td></tr><tr><td>Kick viewers</td><td>Yes</td><td>Yes</td><td>No</td></tr><tr><td>Mute viewers</td><td>Yes</td><td>Yes</td><td>No</td></tr><tr><td>Voice mute / kick</td><td>Yes</td><td>Yes</td><td>No</td></tr><tr><td>Appoint / dismiss moderators</td><td>Yes</td><td>No</td><td>No</td></tr><tr><td>Transfer host, modify room settings</td><td>Yes</td><td>No</td><td>No</td></tr></tbody></table><blockquote><p>Moderators <strong>cannot act on</strong> the host, other moderators, or admin (root/admin) users; <code>root</code> accounts are protected in the room and cannot be muted or kicked.</p></blockquote><h2 id="_5-screen-annotations" tabindex="-1">5. Screen Annotations <a class="header-anchor" href="#_5-screen-annotations" aria-label="Permalink to &quot;5. Screen Annotations&quot;">​</a></h2><p>In Screen Share mode, the host can use the pen tool to draw highlights on the screen, which all viewers can see in real time.</p><h2 id="_6-playback-state-synchronization" tabindex="-1">6. Playback State Synchronization <a class="header-anchor" href="#_6-playback-state-synchronization" aria-label="Permalink to &quot;6. Playback State Synchronization&quot;">​</a></h2><p>When you join a room as a viewer, everything syncs automatically:</p><ul><li>Host plays/pauses/seeks/changes speed -- you follow automatically</li><li>If the host disconnects, the server takes over broadcasting, watching continues uninterrupted</li><li>If the host is offline for more than 10 minutes, the room closes automatically</li></ul><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="can-t-hear-voice" tabindex="-1">Can&#39;t hear voice? <a class="header-anchor" href="#can-t-hear-voice" aria-label="Permalink to &quot;Can&#39;t hear voice?&quot;">​</a></h3><p>Make sure the host has enabled voice, check your speakers, check microphone permissions, and try accessing via HTTPS.</p><h3 id="the-host-didn-t-respond-to-my-request" tabindex="-1">The host didn&#39;t respond to my request? <a class="header-anchor" href="#the-host-didn-t-respond-to-my-request" aria-label="Permalink to &quot;The host didn&#39;t respond to my request?&quot;">​</a></h3><p>The host may not be present. Wait a moment. If auto-approve is enabled, the request takes effect automatically.</p><h3 id="how-do-i-appoint-a-moderator" tabindex="-1">How do I appoint a moderator? <a class="header-anchor" href="#how-do-i-appoint-a-moderator" aria-label="Permalink to &quot;How do I appoint a moderator?&quot;">​</a></h3><p>In the <strong>Viewer Management</strong> panel, the host clicks the shield icon next to a target user to appoint or dismiss a moderator. Only the host can do this, and only logged-in users can be appointed.</p><h3 id="if-i-m-voice-muted-can-i-still-hear-others" tabindex="-1">If I&#39;m voice-muted, can I still hear others? <a class="header-anchor" href="#if-i-m-voice-muted-can-i-still-hear-others" aria-label="Permalink to &quot;If I&#39;m voice-muted, can I still hear others?&quot;">​</a></h3><p>Yes. Voice mute only stops you from speaking (the server relay layer drops your audio packets); listening is unaffected.</p>',40)])])}const p=t(n,[["render",i]]);export{m as __pageData,p as default};
